={{ JSON.stringify($json, (key, value) => {
  if (key !== 'source' || !value || typeof value.text !== 'string' || !Array.isArray($json.sources)) return value;
  const match = $json.sources.find(source => source?.text === value.text && typeof source.id === 'string');
  if (!match) return value;
  const { text, ...metadata } = value;
  return { ...metadata, text: '[Texto integral em sources, id=' + match.id + ']' };
}) }}

