const draft=$('Validar entrada').item.json;
const hold=(reason)=>({json:{post_id:draft.post_id,open_questions:draft.open_questions,pauta_id:draft.pauta_id,briefing:draft.briefing,decision:'reter',reason}});
if($json.status!=='completed'||!Array.isArray($json.output))return hold('Revisão incompleta.');
const parts=$json.output.flatMap(part=>part.content??[]).filter(part=>part.type==='output_text').map(part=>part.text);
let result;
try{result=parts.length===1&&typeof parts[0]==='object'?parts[0]:JSON.parse(parts.join(''));}catch{return hold('Revisão inválida.');}
if(!result||!['revisado','reter'].includes(result.decision)||typeof result.title!=='string'||typeof result.content!=='string'||typeof result.excerpt!=='string'||![result.changes,result.pending].every(items=>Array.isArray(items)&&items.every(text=>typeof text==='string'&&text.trim())))return hold('Revisão inválida.');
if(result.decision==='reter')return {json:{post_id:draft.post_id,open_questions:draft.open_questions,pauta_id:draft.pauta_id,briefing:draft.briefing,decision:'reter',pending:result.pending}};
const normalizedTitle = result.title.replace(/(?:\s*\(\s*(?:[0-3]?\d[/.–-][01]?\d(?:[/.–-](?:\d{4}|\d{2}))?|\d{4}-\d{2}-\d{2})\s*\)|\s+(?:[—–|-]\s*)?(?:[0-3]?\d[/.–-][01]?\d[/.–-](?:\d{4}|\d{2})|\d{4}-\d{2}-\d{2})|\s*\(\s*[0-3]?\d\s+de\s+(?:janeiro|fevereiro|março|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)(?:\s+de\s+\d{4})?\s*\))\s*$/iu, '').trim();
if (normalizedTitle !== result.title.trim()) result.changes.push('Retirou a data avulsa da manchete.');
result.title = normalizedTitle;
const excerpt = result.excerpt.trim();
const normalize = text => text.toLocaleLowerCase('pt-BR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
if (!excerpt || excerpt.length > 1000 || normalize(excerpt) === normalize(result.title)) return hold('Resumo ausente, longo demais ou igual à manchete.');
if(!result.title.trim()||result.title.length>500||!result.content.trim()||result.content.length>42000||!result.changes.length)return hold('Revisão sem texto ou alterações registradas.');
return {json:{post_id:draft.post_id,open_questions:draft.open_questions,pauta_id:draft.pauta_id,briefing:draft.briefing,decision:'revisado',title:result.title,excerpt,content:result.content,changes:result.changes,pending:result.pending}};
